import{j as e}from"./index-EE7B2ooc.js";import{L as r,S as o,a as t,C as n}from"./LegalLayout-B4cZuamX.js";import{R as s}from"./pricing-BqfgmM_a.js";import{L as i}from"./react-vendor-AIXwcq2c.js";const a="altovisas@gmail.com",l="21 October 2026",d=[{id:"covers",title:"What this policy covers"},{id:"final",title:"All sales are final"},{id:"why",title:"Why we don't offer refunds"},{id:"refusal",title:"If your visa is refused"},{id:"mistakes",title:"Billing mistakes we will fix"},{id:"unused",title:"Unused mock interviews"},{id:"ending",title:"If we end the Service or remove a feature"},{id:"law",title:"Your rights under consumer law"},{id:"disputes",title:"Before you dispute a charge"},{id:"contact",title:"How to reach us"},{id:"changes",title:"Changes to this policy"}];function f(){return e.jsxs(r,{title:"Refund Policy",updated:l,toc:d,summary:e.jsxs(n,{children:[e.jsx("p",{className:"doc-callout-h",children:"The short version"}),e.jsx("p",{children:"Altovisas plans are one-time purchases of a digital service that starts working the moment you buy it. For that reason all sales are final and we do not offer refunds, including when a visa is refused. You can try the free mock interview first, with no card. We will always put right a billing mistake, and nothing here takes away rights your local consumer law gives you."})]}),children:[e.jsx(o,{id:"covers",title:"1. What this policy covers",children:e.jsxs("p",{children:["This policy applies to every paid plan listed on our"," ",e.jsx(i,{to:"/pricing",children:"Pricing page"})," (Quick prep, Full prep and Complete) and to any other paid plan we offer on altovisas.com. The free plan costs nothing, so there is nothing to refund. This policy is part of our"," ",e.jsx(i,{to:"/terms",children:"Terms of Service"}),"."]})}),e.jsxs(o,{id:"final",title:"2. All sales are final",children:[e.jsx("p",{children:"Once your payment goes through, the plan is added to your account and you can use it straight away. From that moment the purchase is not refundable, in whole or in part. That holds whether or not you use the mock interviews, and whatever the reason, including:"}),e.jsxs(t,{children:[e.jsx("li",{children:"you changed your mind, or bought the wrong plan;"}),e.jsx("li",{children:"your interview was moved, cancelled, or no longer needed;"}),e.jsx("li",{children:"you did not find the feedback as useful as you hoped;"}),e.jsx("li",{children:"your visa was refused (see section 4 for what the Complete plan includes)."})]})]}),e.jsx(o,{id:"why",title:"3. Why we don't offer refunds",children:e.jsxs(t,{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"You can try before you pay."})," The free mock interview shows you the full feedback format with no card and no charge, so you know what a plan contains before you buy one."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"The service is delivered at once."})," A plan works the moment you buy it, and every mock interview you run costs us money to score. That work cannot be handed back."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"The outcome is not ours to promise."})," Visa decisions are made only by consular officers. A refund tied to the result would suggest we can influence it, and we cannot."]})]})}),e.jsxs(o,{id:"refusal",title:"4. If your visa is refused",children:[e.jsx(n,{children:e.jsx("p",{children:"A visa refusal is not grounds for a refund on any plan. Nothing we sell can change what a consular officer decides."})}),e.jsxs("p",{children:["The Complete plan includes refusal cover. If your F-1 visa is refused after you bought Complete, we add ",s," more mock interviews to your account at no charge, so you can prepare for your next attempt. To claim it, email"," ",a," from the address on your account and tell us your visa was refused. Do not send passport, visa, or DS-160 numbers; we never need them."]}),e.jsx("p",{children:"Refusal cover can be claimed once for each Complete purchase. It is extra practice, not money: it cannot be exchanged for cash, a refund, or a different plan."})]}),e.jsxs(o,{id:"mistakes",title:"5. Billing mistakes we will fix",children:[e.jsx("p",{children:"All sales being final never means you pay for our mistakes. We will put right:"}),e.jsxs(t,{children:[e.jsx("li",{children:"a charge made more than once for the same purchase;"}),e.jsx("li",{children:"a charge for a different amount from the price shown when you paid;"}),e.jsx("li",{children:"a payment that went through without the plan reaching your account, where we cannot fix that promptly;"}),e.jsx("li",{children:"a charge you did not make or authorise. Tell your bank as well as us."})]}),e.jsx("p",{children:"Depending on what went wrong, we will either deliver what you paid for or refund the mistaken amount to the payment method you used. Tell us as soon as you notice the problem. Refunds usually take a few working days to appear, depending on your bank."})]}),e.jsx(o,{id:"unused",title:"6. Unused mock interviews",children:e.jsx("p",{children:"Mock interviews you have not used have no cash value. They cannot be refunded, moved to another account, or exchanged for money or for a different plan."})}),e.jsx(o,{id:"ending",title:"7. If we end the Service or remove a feature",children:e.jsxs("p",{children:["If we close Altovisas, or permanently remove a feature included in a plan you bought before you have been able to use it, we will refund the part of the price that covers what you could not use. If we close your account because you broke our"," ",e.jsx(i,{to:"/terms",children:"Terms of Service"}),", no refund is due."]})}),e.jsxs(o,{id:"law",title:"8. Your rights under consumer law",children:[e.jsx("p",{children:"This policy does not take away any right that the consumer law of the country you live in gives you and does not allow to be waived. If the law where you live gives you a right to cancel or to a refund, we will honour it."}),e.jsx("p",{children:"If you live in the European Union or the United Kingdom, consumer law usually gives you 14 days to cancel an online purchase. For a digital service that starts immediately, that right can end once you begin using it, if you asked for immediate access and acknowledged that you would lose the right to cancel. Where the law still gives you a right to cancel, this policy does not override it."})]}),e.jsx(o,{id:"disputes",title:"9. Before you dispute a charge",children:e.jsx("p",{children:"Please email us before you open a dispute or chargeback with your bank. A billing mistake is usually put right faster by us than through a bank dispute, and we would rather fix it directly."})}),e.jsx(o,{id:"contact",title:"10. How to reach us",children:e.jsxs("p",{children:["Write to"," ",e.jsx("a",{href:`mailto:${a}`,children:a})," ","from the email address on your account. Include the date and amount of the charge, the plan you bought, and what went wrong. We aim to reply within a few working days."]})}),e.jsx(o,{id:"changes",title:"11. Changes to this policy",children:e.jsx("p",{children:'We may update this policy. The "Last updated" date above shows the current version. A purchase is always governed by the version in force on the day you paid; a later change never applies to a plan you have already bought.'})})]})}export{f as default};
